{"packet_id":"D010-01","doc_id":"D010","jurisdiction":"Boston, MA","category":"screening_restrictions","lifecycle":"enacted","title":"Boston Fair Chance Tenant Selection Policy criminal and credit screening rules","requirement":"A housing provider may not impose a blanket policy denying housing to anyone with arrests or convictions; it must review applicants case by case, disregarding non-convictions, sealed or juvenile records, and convictions older than five years, and may not use credit scores to approve or deny applications.","key_value":"5-year conviction lookback","coverage_conditions":"Housing providers receiving DND funding and/or land, or with income-restricted units created under the BPDA Inclusionary Development Policy; also applied to the Office of Fair Housing and Equity Affirmative Marketing Program.","applicability":{"conditions":[{"type":"other","role":"covered","text":"Providers receiving DND funding and/or land, or with income-restricted units under the BPDA Inclusionary Development Policy"}],"per_tenancy":"Policy does not apply where a conviction directly relates to the housing sought or poses an unreasonable risk of substantial harm to others; current criminal behavior excluded.","coverage_quotes":["Housing providers receiving Department of Neighborhood Development (DND) funding and/or land, or that have income restricted units created under the Boston Planning and Development Agency (BPDA) Inclusionary Development Policy will not impose a blanket policy that denies housing to anyone with arrests and or convictions."]},"exemptions":"Exceptions where a conviction directly relates to the housing sought or poses an unreasonable risk of substantial harm to others; current criminal behavior; conflicting federal or state criminal history law preempts the policy.","penalty":null,"effective_date":"2017-02","valid_through":null,"citation":"Boston Fair Chance Tenant Selection Policy","quoted_span":"Housing providers receiving Department of Neighborhood Development (DND) funding and/or land, or that have income restricted units created under the Boston Planning and Development Agency (BPDA) Inclusionary Development Policy will not impose a blanket policy that denies housing to anyone with arrests and or convictions. Housing providers will consider applicants on a case-by-case basis.","interaction":"Conflicting federal or state criminal history requirements preempt this policy.","relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D010-01","doc_id":"D010","jurisdiction":"Boston, MA","category":"just_cause_eviction","lifecycle":"enacted","title":"Boston Fair Chance Tenant Selection Policy limits on criminal records in eviction decisions","requirement":"A participating housing provider may not consider arrests without conviction, convictions with judicial relief such as sealing, juvenile records, or convictions more than five years old when deciding whether to evict a tenant.","key_value":"5-year conviction lookback","coverage_conditions":"Housing providers receiving DND funding and/or land, or with income-restricted units created under the BPDA Inclusionary Development Policy; also applied to the Office of Fair Housing and Equity Affirmative Marketing Program.","applicability":{"conditions":[{"type":"other","role":"covered","text":"Providers receiving DND funding and/or land, or with income-restricted units under the BPDA Inclusionary Development Policy"}],"per_tenancy":"Policy does not apply where a conviction directly relates to the housing sought or poses an unreasonable risk of substantial harm to others; current criminal behavior excluded.","coverage_quotes":["Housing providers receiving Department of Neighborhood Development (DND) funding and/or land, or that have income restricted units created under the Boston Planning and Development Agency (BPDA) Inclusionary Development Policy will not impose a blanket policy that denies housing to anyone with arrests and or convictions."]},"exemptions":"Exceptions where a conviction directly relates to the housing sought or poses an unreasonable risk of substantial harm to others; current criminal behavior; conflicting federal or state criminal history law preempts the policy.","penalty":null,"effective_date":"2017-02","valid_through":null,"citation":"Boston Fair Chance Tenant Selection Policy","quoted_span":"The Developer/Agent (Agent) agrees to not consider any of the following categories when determining housing eligibility and or considering eviction:","interaction":"Conflicting federal or state criminal history requirements preempt this policy.","relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
